                    StateHasChanged();
                    ShowPopup = true;
                    return;
                }
                transportFee.IsValid = true;
                transportFee.GroupCode = groupcode;
                transportFee.CreatedBy = UserName;
                //transportFee.CreatedDate = DateTime.Now;
                string apiUrl = "TransportFee/AddOrUpdateTransport";

                var apiResponse = await httpService.Post<ApiResponse<object>>(apiUrl, transportFee);

                var responsecode = apiResponse.Code;
                if (responsecode == 0)
                {
                    await Alert.ShowWarning("Transport Fee" + @Localizer["Already"]);
                }
                else if (responsecode == 1)
                {
                    await Alert.ShowSuccess("Transport Fee" + @Localizer["Inserted"]);
                }
                else if (responsecode == 2)
                {
                    await Alert.ShowUpdate("Transport Fee" + @Localizer["Updated"]);
                }
                else
                {
                    await Alert.ShowCustomAlert(@Localizer["Admin"]);
                }

                await LoadData();
                transportFee = new TransportFeeConfig();
            }
            catch (Exception ex)
